#include <stdio.h>

static int first(void) {
    puts("first() evaluated");
    return 10;
}

static int second(void) {
    puts("second() evaluated");
    return 20;
}

int main(void) {
    int total = first() + second();
    printf("total=%d\n", total);
    return 0;
}
